"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[11518],{85044:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ThrowableHandler","desc":"Category handler for thrown weapons (grenade + C4). On activate it gates on the\\nthrow cooldown, plays the throw sound, and sends `ReqThrowProjectile`. The\\nprojectile instance is server-spawned and replicates to every client (no local\\ncosmetic). Manual detonation (C4) is handled globally by\\nThrowableDetonateController, which sends `ReqDetonate` on G regardless of the\\nequipped Tool. Damage + detonation are server-side.","realm":["Client"],"source":{"line":13,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/ThrowableHandler.luau"}}')}}]);